head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[accordion > P > unCollapseAll]<br/>Accordion 컴포넌트의 초기 렌더링 시 모든 패널을 펼칠지 설정합니다.",
    "validation" : [
        "unCollapseAll=false (default) 이고 selectedPanel 속성을 설정하지 않으면 첫 번째 비활성화(disabled)되지 않은 패널만 열린 상태로 렌더링됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (unCollapseAll 미설정 + selectedPanel 미설정 환경에서 첫 번째 비-disabled 패널 자동 열림 검증)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (unCollapseAll 생략 → default false, selectedPanel 생략)
    let properties = {};

    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="* panels1 (활성), panels2 (활성), panels3 (disabledPanels=true) → 첫 번째 비-disabled 패널인 panels1 이 초기에 열린 상태로 렌더링되는지 확인"', '', 'label1');
    $c.gcm.createLabel('label="* 열린 패널 확인 버튼으로 getOpenPanelListInfo 결과가 panels1 한 개인지 확인"', '', 'label2');

    strTarget += '<w2:accordion ' + strNameSpace + ' ' + cList + ' id="" style="width:240px; height:320px;">';
    strTarget += '<w2:panels style="" id="panels1" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle1" label="panelTitle1"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent1">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel1"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels2" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle2" label="panelTitle2"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent2">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel2"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels3" class="" disabledPanels="true">';
    strTarget += '<w2:panelTitle style="" id="panelTitle3" label="panelTitle3 (disabled)"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent3">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel3"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '</w2:accordion>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "accordion",
        strTarget,
        grp_comp
    );
}



// 현재 열린 패널 정보 출력
scwin.btn_getOpenPanel_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== getOpenPanelListInfo() 결과 =====");
    let openList = target1.getOpenPanelListInfo();
    wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 수 : " + (openList ? openList.length : 0));
    if (openList && openList.length > 0) {
        for (let i = 0; i < openList.length; i++) {
            wf_body_bottom.getObj("scwin").setReturnValue("열린 패널[" + i + "] id : " + openList[i].id);
        }
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 없음 (모두 닫힘)");
    }
};
